def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most common color is the background.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    separator_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    separator_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]

    if separator_rows and (not separator_cols or len(separator_rows) >= len(separator_cols)):
        period = separator_rows[0] + 1
        # Combine clues from corresponding rows, then repeat the pattern.
        pattern = [[background] * w for _ in range(period)]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != background:
                    pattern[r % period][c] = grid[r][c]
        return [pattern[r % period][:] for r in range(h)]

    if separator_cols:
        period = separator_cols[0] + 1
        pattern = [[background] * period for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if grid[r][c] != background:
                    pattern[r][c % period] = grid[r][c]
        return [[pattern[r][c % period] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
